    public static function Ertekeles(?float $ertek, ?int $elem_id = 0) : void {
        if($ertek === null)
            $ertek = 0;
        for($i = 1; $i < 6; $i++) {
            if($ertek >= $i - 0.2)
                $csillag = self::$ikonok['telicsillag'];
            elseif($ertek >= $i - 0.7)
                $csillag = self::$ikonok['felcsillag'];
            else
                $csillag = self::$ikonok['urescsillag'];

            echo sprintf($csillag, $i, $elem_id);
        }
    }

    public static function HorizontalSep() : void {
        echo '<div class="horizontal-separator"></div>';
    }
}